qs=[]
for i,r in enumerate(rows):
 a=list(r[1:5]);k=i%4;qs.append(dict(spec='ksk',station=i//5,q=r[0],a=a[k:]+a[:k],c=(4-k)%4,fact=r[5]))
for name in ['questions.json','data/questions.json']:
 p=Path(name);raw=p.read_text(encoding='utf-8-sig');assert not any(q.get('spec')=='ksk' for q in json.loads(raw))
 end=raw.rfind(']');p.write_text(raw[:end].rstrip()+',\n'+',\n'.join(json.dumps(q,ensure_ascii=False,indent=2) for q in qs)+'\n]\n',encoding='utf-8')
Path('specialties/ksk/questions.js').write_text('window.KSK_QUESTIONS = '+json.dumps(qs,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
# Reuse local browser verification, with KSK map positions and a no-repeat assertion.
s=Path('.qa/check.cjs').read_text(encoding='utf-8').replace('#nodeP','#nodeKsk').replace('spec=p','spec=ksk').replace("q.spec==='p'","q.spec==='ksk'").replace("'.qa/it-","'.qa/ksk-")
s=s.replace('player.gx=6;player.gy=6;tryMove(0,-1);','player.gx=5;player.gy=5;tryMove(0,-1);').replace("player.gy),6)","player.gy),5)")
s=s.replace("assert.equal(await page.evaluate(()=>state),'playing');\nawait page.screenshot", "assert.equal(await page.evaluate(()=>state),'playing');\nconst earned=await page.evaluate(()=>score);await page.evaluate(()=>{openQuestion(crystals[0]);tapTo(crystals[0]);});assert.equal(await page.evaluate(()=>score),earned);assert.equal(await page.evaluate(()=>state),'playing');await page.evaluate(()=>stopAuto());\nawait page.screenshot")
Path('.qa/check-ksk.cjs').write_text(s,encoding='utf-8')
